package com.ecole.gestion_scolaire.hr.entity;
import com.ecole.gestion_scolaire.school.entity.*; import com.ecole.gestion_scolaire.hr.enums.AssignmentStatus; import jakarta.persistence.*; import java.time.*;
@Entity @Table(name="teaching_assignment") public class TeachingAssignment {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="school_year_id") private SchoolYear schoolYear; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="teacher_id") private Teacher teacher; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="subject_id") private Subject subject; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="class_group_id") private ClassGroup classGroup; @Column(name="start_date",nullable=false) private LocalDate startDate; @Column(name="end_date") private LocalDate endDate; @Enumerated(EnumType.STRING) @Column(nullable=false,length=30) private AssignmentStatus status; @Column(name="created_at",nullable=false) private OffsetDateTime createdAt; @Column(name="updated_at",nullable=false) private OffsetDateTime updatedAt;
 @PrePersist void pre(){var n=OffsetDateTime.now();createdAt=n;updatedAt=n;if(status==null)status=AssignmentStatus.ACTIVE;} @PreUpdate void upd(){updatedAt=OffsetDateTime.now();}
 public Long getId(){return id;} public SchoolYear getSchoolYear(){return schoolYear;} public void setSchoolYear(SchoolYear v){schoolYear=v;} public Teacher getTeacher(){return teacher;} public void setTeacher(Teacher v){teacher=v;} public Subject getSubject(){return subject;} public void setSubject(Subject v){subject=v;} public ClassGroup getClassGroup(){return classGroup;} public void setClassGroup(ClassGroup v){classGroup=v;} public LocalDate getStartDate(){return startDate;} public void setStartDate(LocalDate v){startDate=v;} public LocalDate getEndDate(){return endDate;} public void setEndDate(LocalDate v){endDate=v;} public AssignmentStatus getStatus(){return status;} public void setStatus(AssignmentStatus v){status=v;}
}